const chaptersRaw = [
  ["A Vila Esquecida", "A névoa desce sobre Valedouro antes mesmo do anoitecer, espessa o bastante para apagar as casas do outro lado da rua.\nNas portas, marcas negras parecem ter sido queimadas de dentro para fora; nenhuma fechadura foi arrombada, mas as mesas continuam postas e as lareiras ainda guardam brasas frias.\nDo fundo do poço central vem o som de um sino, abafado pela terra, marcando um ritmo que ninguém da vila reconhece.\nJunto à capela, Maelis, uma cartógrafa de olhos fundos e mãos cobertas de tinta, espera entre os únicos rastros que a névoa não conseguiu apagar.\nEla conta que seu irmão Tomas tocou o sino na noite do desaparecimento e foi a última pessoa vista na praça; desde então, o som vem debaixo das pedras.\nMaelis entrega a você uma fita arrancada do sino e um mapa incompleto, desenhado às pressas antes que as ruas mudassem de lugar.\n“Não preciso que prometa salvar a vila”, diz ela, tentando conter o tremor na voz. “Só descubra o que está chamando os nossos nomes lá de baixo, antes que a névoa alcance a estrada.”", "Lobos rondam os poços e uma criatura maior guarda a antiga praça.", "Encontre a origem da névoa e recupere o sino da vila.", [
    enemy("c01_lobo", "Lobo das Sombras", "normal", 42, 8, 22, 14, [{item:"presa_sombria",chance:0.55},{item:"pocao_vida",chance:0.12}], "Predador corrompido pela névoa."),
    enemy("c01_vulto", "Vulto de Palha", "elite", 58, 10, 32, 21, [{item:"flor_lua",chance:0.35},{item:"cristal_arcano",chance:0.12}], "Um espantalho que se move sem vento."),
    enemy("c01_guardiao", "Guardião do Sino", "boss", 105, 13, 75, 55, [{item:"chave_ruinas",chance:1},{item:"tunica_couro",chance:0.2}], "Um antigo protetor dominado pela corrupção.")
  ]],
  ["A Estrada dos Corvos", "Além dos últimos muros de Valedouro, uma estrada estreita serpenteia entre árvores tortas e carroças abandonadas.\nCorvos acompanham cada passo pelos galhos, mas não grasnam: repetem sussurros humanos, inclusive palavras que você ainda não disse.\nPerto de uma ponte de madeira, pegadas recentes desaparecem no barro sem deixar marcas de retorno.\nUm viajante escondido sob os restos de uma carroça aponta para pequenas fitas negras amarradas aos troncos, sinal usado por saqueadores.\nSe alguém está guiando aquelas aves, a trilha leva ao altar escondido antes que a próxima caravana desapareça.", "Batedores saqueiam viajantes para alimentar um altar escondido.", "Cruze a estrada e descubra quem está guiando os corvos.", [
    enemy("c02_corvo", "Corvo Ferrugem", "normal", 55, 11, 28, 18, [{item:"flor_lua",chance:0.4}]),
    enemy("c02_saqueador", "Saqueador da Estrada", "elite", 78, 13, 42, 28, [{item:"pocao_vida",chance:0.18},{item:"presa_sombria",chance:0.35}]),
    enemy("c02_capitao", "Capitão dos Corvos", "boss", 135, 17, 95, 70, [{item:"adaga_lua",chance:0.2},{item:"cristal_arcano",chance:0.6}])
  ]],
  ["O Bosque que Sussurra", "As árvores se fecham atrás de você, entrelaçando galhos como dedos que tentam impedir a passagem.\nO ar cheira a folhas molhadas e cinzas, e cada rajada traz uma voz diferente chamando de dentro dos troncos ocos.\nNo chão, flores pálidas se abrem quando sua sombra passa e murcham assim que você olha diretamente para elas.\nUma figura encapuzada surge entre as raízes, mas seu rosto é apenas um reflexo distorcido de quem está olhando.\nNo coração do bosque, algo pulsa sob a terra e espalha a mesma corrupção que cobriu as casas de Valedouro.", "Espíritos vegetais e caçadores enlouquecidos defendem o coração do bosque.", "Encontre a raiz da corrupção sem entregar suas memórias.", [
    enemy("c03_esporo", "Esporo Errante", "normal", 70, 13, 36, 22, [{item:"flor_lua",chance:0.65}]),
    enemy("c03_cacador", "Caçador Enfeitiçado", "elite", 95, 16, 52, 34, [{item:"arco_freixo",chance:0.12},{item:"presa_sombria",chance:0.4}]),
    enemy("c03_raiz", "Raiz-Mãe Corrompida", "boss", 170, 20, 120, 90, [{item:"cristal_arcano",chance:0.75},{item:"anel_vigor",chance:0.18}])
  ]],
  ["A Ponte Partida", "O caminho termina diante de uma ponte antiga, rachada ao meio sobre um abismo que não devolve o som das pedras.\nTochas azuis ardem do outro lado, embora não haja vento nem sinal de quem as acendeu.\nCorrentes grossas balançam sozinhas, e marcas recentes de botas mostram que alguém atravessou apesar do perigo.\nEntre os pilares, mercenários vigiam a passagem e recolhem qualquer objeto que brilhe com energia arcana.\nPara alcançar a fortaleza além do desfiladeiro, você terá de encontrar uma travessia ou abrir caminho à força.", "Mercenários e sentinelas impedem a travessia.", "Abra caminho até a fortaleza e impeça que reforços cheguem à névoa.", [
    enemy("c04_mercenario", "Mercenário Cinzento", "normal", 88, 17, 43, 30, [{item:"tunica_couro",chance:0.12}]),
    enemy("c04_sentinnela", "Sentinela de Pedra", "elite", 120, 19, 62, 42, [{item:"escudo_carvalho",chance:0.18}]),
    enemy("c04_carrasco", "Carrasco da Ponte", "boss", 205, 24, 145, 105, [{item:"espada_aventureiro",chance:0.18},{item:"cristal_arcano",chance:0.65}])
  ]],
  ["O Mercado das Lanternas", "Miralume surge ao cair da noite, escondida atrás de colinas e iluminada por lanternas que flutuam sem cordas.\nAs barracas vendem mapas sem estradas, frascos cheios de luz e lembranças que ninguém admite ter perdido.\nPor trás da música dos comerciantes, cobradores percorrem as vielas recolhendo moedas em nome de uma guilda que não aparece em nenhum registro.\nUma mercadora de olhar atento oferece abrigo por alguns minutos e avisa que a cidade inteira teme quem controla os contratos.\nAntes de seguir para as minas sob as ruas, você precisa decidir em quem confiar e quais suprimentos serão indispensáveis.", "Agentes de uma guilda tentam tomar o mercado à força.", "Negocie com Nara, reabasteça-se e descubra quem financia a guilda.", [
    enemy("c05_cobrador", "Cobrador da Guilda", "normal", 105, 19, 50, 42, [{item:"pocao_grande",chance:0.18}]),
    enemy("c05_lamina", "Lâmina Contratada", "elite", 140, 22, 72, 55, [{item:"adaga_lua",chance:0.16}]),
    enemy("c05_mestre", "Mestre dos Contratos", "boss", 245, 27, 170, 150, [{item:"anel_sabio",chance:0.15},{item:"cristal_arcano",chance:0.8}])
  ]],
  ["As Minas de Vidro", "Sob as ruas de Miralume, túneis de cristal espalham reflexos que não correspondem aos movimentos de quem passa.\nPicaretas permanecem suspensas no ar, como se os mineiros tivessem largado o trabalho no meio de um golpe e nunca voltado.\nUma parede translúcida pulsa em intervalos lentos, iluminando as galerias como um coração enterrado na pedra.\nAo tocar o chão, você sente vibrações que sobem pelos ossos e formam uma sequência quase semelhante a uma voz.\nSe o núcleo continuar crescendo, toda a montanha poderá se partir e liberar aquilo que os trabalhadores despertaram.", "Golems de vidro e larvas cristalinas guardam os túneis.", "Desative o coração mineral antes que a mina desabe.", [
    enemy("c06_larva", "Larva Prismática", "normal", 120, 22, 58, 38, [{item:"cristal_arcano",chance:0.6}]),
    enemy("c06_golem", "Golem Vítreo", "elite", 160, 25, 80, 52, [{item:"escudo_carvalho",chance:0.14}]),
    enemy("c06_coracao", "Coração de Quartzo", "boss", 280, 30, 195, 125, [{item:"lamina_rubi",chance:0.12},{item:"cristal_arcano",chance:1}])
  ]],
  ["A Abadia Sem Voz", "No alto de uma encosta, uma abadia cinzenta resiste à chuva, cercada por sinos rachados que jamais produzem som.\nOs monges se comunicam por gestos e evitam olhar para o vitral da entrada, onde uma silhueta parece mudar de posição quando ninguém observa.\nA biblioteca foi revirada; páginas arrancadas cobrem o chão e os mapas celestes terminam sempre na mesma mancha escura.\nUm guardião ferido entrega a você um fragmento de pergaminho, insistindo que o arquivo proibido não pode cair nas mãos erradas.\nEntre os corredores silenciosos, há pistas sobre uma porta negra e sobre o motivo de sua imagem aparecer no vidro.", "Acólitos corrompidos protegem o arquivo proibido.", "Recupere o mapa celeste e descubra por que sua imagem aparece no vitral.", [
    enemy("c07_acolito", "Acólito Mudo", "normal", 140, 24, 65, 43, [{item:"cristal_arcano",chance:0.3}]),
    enemy("c07_cavaleiro", "Cavaleiro Penitente", "elite", 185, 28, 92, 62, [{item:"manto_arcanista",chance:0.14}]),
    enemy("c07_abade", "Abade do Silêncio", "boss", 325, 34, 220, 145, [{item:"manto_arcanista",chance:0.25},{item:"chave_ruinas",chance:0.35}])
  ]],
  ["O Pântano dos Nomes", "O pântano começa sem aviso: a trilha firme cede sob seus pés e a água escura engole o reflexo das árvores.\nBolhas sobem da lama pronunciando nomes de pessoas que você nunca conheceu, seguidas por vozes que parecem imitar seus pensamentos.\nUma barqueira espera numa plataforma de raízes e avisa para não responder a chamado algum, nem mesmo ao ouvir a própria voz.\nLuzes verdes marcam um caminho entre os juncos, mas se apagam sempre que você tenta contá-las.\nDo outro lado, uma torre afundada emerge da névoa e faz as águas girarem ao redor de suas paredes.", "Afogados e sanguessugas espectrais surgem sob a água escura.", "Atravesse o pântano e encontre a torre afundada.", [
    enemy("c08_afogado", "Afogado Errante", "normal", 160, 27, 72, 48, [{item:"presa_sombria",chance:0.5}]),
    enemy("c08_sanguessuga", "Sanguessuga Espectral", "elite", 205, 30, 102, 68, [{item:"elixir_total",chance:0.1}]),
    enemy("c08_noiva", "Noiva do Lodo", "boss", 360, 37, 245, 165, [{item:"anel_vigor",chance:0.22},{item:"cristal_arcano",chance:0.8}])
  ]],
  ["A Torre Afundada", "A torre ergue-se do pântano com as janelas submersas e engrenagens visíveis atrás de paredes cobertas de limo.\nCada degrau parece levar a uma hora diferente: poeira cai para cima, velas se reacendem e pegadas antigas aparecem diante de você.\nEm salas repetidas, ecos de soldados revivem os últimos segundos de uma batalha que ninguém venceu.\nNo topo, um relógio enorme continua funcionando apesar de não possuir ponteiros, movido por uma luz presa em seu mecanismo.\nDestruí-lo pode libertar a região do ciclo, mas também revelar o que foi mantido no passado por tanto tempo.", "Construtos temporais defendem o mecanismo no topo.", "Destrua o relógio que mantém a corrupção presa no passado.", [
    enemy("c09_relogio", "Carrapato de Relógio", "normal", 180, 30, 82, 55, [{item:"cristal_arcano",chance:0.5}]),
    enemy("c09_construto", "Construto Temporal", "elite", 235, 34, 118, 78, [{item:"botas_cacador",chance:0.13}]),
    enemy("c09_mestre", "Mestre dos Segundos", "boss", 410, 42, 280, 190, [{item:"lamina_rubi",chance:0.18},{item:"selo_primordial",chance:0.25}])
  ]],
  ["O Festival da Lua Rubra", "A cidade inteira veste máscaras durante o festival, mas nenhuma delas mostra um rosto verdadeiro.\nLanternas vermelhas percorrem o céu em silêncio, e as sombras dos moradores apontam para o palco mesmo quando seus corpos seguem outra direção.\nUma mensagem escondida sob os degraus revela que a celebração não é uma festa, mas parte de um ritual preparado há gerações.\nEntre músicos e dançarinos, agentes disfarçados protegem um conselheiro que nunca projeta sombra.\nQuando a lua alcançar o centro do céu, o ritual abrirá uma passagem que talvez não possa ser fechada novamente.", "Máscaras vivas e duelistas protegem o palco ritual.", "Interrompa a cerimônia e recupere o primeiro selo primordial.", [
    enemy("c10_mascara", "Máscara Faminta", "normal", 205, 33, 92, 65, [{item:"flor_lua",chance:0.4}]),
    enemy("c10_duelista", "Duelista Rubro", "elite", 270, 38, 135, 95, [{item:"lamina_rubi",chance:0.12}]),
    enemy("c10_conselheiro", "Conselheiro Sem Sombra", "boss", 470, 47, 330, 260, [{item:"selo_primordial",chance:1},{item:"anel_sabio",chance:0.2}])
  ]],
  ["O Deserto de Cinzas", "Depois das últimas muralhas, o terreno se transforma num mar de cinzas que cobre estradas, telhados e até os esqueletos das árvores.\nCaravanas abandonadas formam uma linha de silêncio pelo deserto, com bússolas girando e cantis cheios de areia fina.\nÀ noite, estrelas aparecem sob seus pés, como se o céu tivesse sido enterrado e continuasse tentando brilhar.\nUm mapa queimado aponta para um observatório soterrado onde estudiosos tentaram prever a chegada da Fenda.\nA tempestade se aproxima, e cada minuto perdido torna mais difícil distinguir o caminho das miragens.", "Escorpiões de cinza e saqueadores disputam os restos das caravanas.", "Atravesse as dunas e recupere as cartas estelares.", [
    enemy("c11_escorpiao", "Escorpião de Cinza", "normal", 235, 36, 105, 72, [{item:"escama_draconica",chance:0.12}]),
    enemy("c11_saqueador", "Saqueador Solar", "elite", 305, 41, 150, 105, [{item:"pocao_grande",chance:0.2}]),
    enemy("c11_colosso", "Colosso de Areia", "boss", 530, 51, 360, 230, [{item:"armadura_guardiao",chance:0.14},{item:"cristal_arcano",chance:1}])
  ]],
  ["O Observatório Partido", "No alto de um planalto, o observatório permanece inclinado, com cúpulas abertas e lentes quebradas apontadas para um céu sem constelações.\nOs registros preservados revelam que a Fenda não caiu do firmamento: foi construída para aprisionar uma estrela consciente.\nAs anotações terminam abruptamente, cobertas por marcas de unhas e cálculos repetidos até rasgar o papel.\nNo salão principal, uma lente intacta projeta uma imagem de um lugar que não existe no mapa e que parece observar de volta.\nReativar o mecanismo pode revelar uma fraqueza no selo, mas também fará algo do outro lado perceber sua presença.", "Astrólogos enlouquecidos e sentinelas orbitais defendem a lente.", "Reative o observatório e olhe para além da Fenda.", [
    enemy("c12_astrologo", "Astrólogo Desfeito", "normal", 260, 39, 118, 80, [{item:"cristal_arcano",chance:0.6}]),
    enemy("c12_sentinela", "Sentinela Orbital", "elite", 335, 44, 168, 118, [{item:"manto_arcanista",chance:0.16}]),
    enemy("c12_lente", "Guardião da Lente", "boss", 590, 55, 395, 250, [{item:"anel_sabio",chance:0.22},{item:"selo_primordial",chance:0.35}])
  ]],
  ["A Floresta Petrificada", "Além das montanhas, uma floresta inteira está transformada em pedra, congelada no instante em que uma tempestade de luz atravessou o vale.\nFolhas minerais tilintam ao vento e troncos partidos revelam anéis que brilham como brasas sob a superfície cinzenta.\nNo centro, uma árvore azul continua viva, pulsando lentamente como se guardasse milhares de vozes em seu interior.\nAo se aproximar, você reconhece fragmentos de lembranças que pertencem aos moradores desaparecidos de Valedouro.\nAs memórias estão presas por uma força que desperta as feras fossilizadas sempre que alguém tenta libertá-las.", "Bestas fossilizadas despertam quando você se aproxima.", "Libere as memórias presas na árvore azul.", [
    enemy("c13_fossil", "Fera Fossilizada", "normal", 285, 42, 130, 88, [{item:"escama_draconica",chance:0.2}]),
    enemy("c13_guardiao", "Guardião Petrificado", "elite", 365, 47, 185, 130, [{item:"armadura_guardiao",chance:0.12}]),
    enemy("c13_arvore", "Coração de Pedra", "boss", 650, 60, 440, 285, [{item:"espada_aurora",chance:0.08},{item:"cristal_arcano",chance:1}])
  ]],
  ["A Cidade Debaixo da Cidade", "Uma escadaria desce por baixo das raízes e termina numa cidade intacta, iluminada por um sol que nunca se move.\nOs habitantes repetem conversas antigas, abrem portas para visitantes que não existem e não percebem a poeira acumulada nos próprios ombros.\nRelógios parados marcam a mesma hora em todas as praças, enquanto guardas sem idade patrulham ruas que não levam a lugar algum.\nNum arquivo subterrâneo, desenhos mostram a construção de uma prisão ao redor de uma estrela viva.\nO arquiteto dessa obra ainda pode estar aqui, preso no mesmo instante em que condenou a cidade inteira ao esquecimento.", "Guardas sem tempo patrulham as ruas imóveis.", "Encontre o arquiteto da prisão estelar.", [
    enemy("c14_guarda", "Guarda Imóvel", "normal", 310, 45, 142, 96, [{item:"pocao_grande",chance:0.2}]),
    enemy("c14_escriba", "Escriba do Vazio", "elite", 395, 51, 200, 142, [{item:"cristal_arcano",chance:0.7}]),
    enemy("c14_arquiteto", "Arquiteto da Prisão", "boss", 720, 66, 485, 310, [{item:"selo_primordial",chance:0.6},{item:"lamina_rubi",chance:0.18}])
  ]],
  ["A Forja dos Juramentos", "A forja ancestral permanece acesa sem combustível, alimentada por juramentos gravados nas paredes de metal negro.\nCada martelo que repousa sobre a bigorna sussurra uma promessa feita por alguém que nunca voltou para cumpri-la.\nUm artesão de mãos cobertas por fuligem explica, sem erguer os olhos, que os selos só respondem a verdades ditas sem proteção.\nNo centro da oficina, uma arma incompleta aguarda materiais retirados das regiões corrompidas.\nPara prepará-la contra a estrela, você terá de reacender a forja e decidir qual promessa merece ser mantida quando tudo estiver em risco.", "Forjados de metal vivo testam a força de cada juramento.", "Reacenda a forja e prepare uma arma capaz de ferir a estrela.", [
    enemy("c15_forjado", "Forjado Incandescente", "normal", 340, 49, 155, 108, [{item:"escama_draconica",chance:0.25}]),
    enemy("c15_martelo", "Martelo Juramentado", "elite", 435, 56, 220, 155, [{item:"espada_aurora",chance:0.1}]),
    enemy("c15_mestre", "Mestre da Forja", "boss", 790, 73, 540, 380, [{item:"espada_aurora",chance:0.18},{item:"selo_primordial",chance:1}])
  ]],
  ["O Mar Suspenso", "Uma escadaria feita de água sobe pelas nuvens e termina num oceano suspenso sobre o mundo.\nNavios naufragados flutuam de lado no céu, presos entre correntes de espuma que não caem e ondas que se movem contra o vento.\nCriaturas abissais circulam sob o casco das embarcações, atraídas por uma bússola que aponta para um lugar impossível.\nEntre os destroços, um diário encharcado descreve uma rota que muda sempre que alguém tenta registrá-la.\nSem a bússola, a passagem até a Fenda continuará escondida dentro da própria tempestade.", "Corsários espectrais e monstros abissais atacam os convés abandonados.", "Recupere a bússola que aponta para aquilo que não deveria existir.", [
    enemy("c16_corsario", "Corsário Espectral", "normal", 370, 52, 170, 120, [{item:"anel_vigor",chance:0.16}]),
    enemy("c16_serpente", "Serpente de Nuvem", "elite", 475, 59, 245, 175, [{item:"escama_draconica",chance:0.5}]),
    enemy("c16_leviata", "Leviatã Suspenso", "boss", 860, 78, 600, 420, [{item:"armadura_guardiao",chance:0.2},{item:"selo_primordial",chance:0.4}])
  ]],
  ["O Reino do Avesso", "A bússola abre uma passagem para um reino espelhado onde o céu se estende sob os pés e as montanhas pairam como ilhas.\nEm cada janela aparece uma vida diferente: escolhas abandonadas, promessas quebradas e caminhos que nunca foram percorridos.\nUma figura com seu mesmo porte surge ao longe e repete seus gestos com um atraso quase imperceptível.\nEla afirma que a Fenda é a única saída para impedir uma catástrofe maior, mas suas palavras mudam quando o reflexo desvia o olhar.\nPara descobrir a verdade, você terá de atravessar o reino sem confundir o que é real com aquilo que gostaria de ter escolhido.", "Reflexos hostis imitam suas técnicas e exploram suas fraquezas.", "Derrote seu reflexo e descubra a verdade por trás da estrela.", [
    enemy("c17_reflexo", "Reflexo Errante", "normal", 400, 56, 185, 132, [{item:"elixir_total",chance:0.16}]),
    enemy("c17_duplo", "Duplo de Prata", "elite", 510, 64, 260, 190, [{item:"lamina_rubi",chance:0.2}]),
    enemy("c17_sombra", "Seu Outro Eu", "boss", 930, 84, 660, 460, [{item:"espada_aurora",chance:0.2},{item:"selo_primordial",chance:0.5}])
  ]],
  ["O Cerco da Fenda", "As forças reunidas pelos sobreviventes cercam a fortaleza final enquanto o chão se dobra sob uma gravidade instável.\nOs três selos vibram em suas mãos, projetando lembranças de lugares que foram apagados antes mesmo de existirem.\nAliados avançam entre ruínas flutuantes, mas cada passo abre fendas menores que tentam puxá-los para longe do campo de batalha.\nDo outro lado do portal, uma luz imensa desperta e transforma o horizonte numa parede de estrelas em movimento.\nVocê precisa alcançar o núcleo antes que a passagem consuma a última rota de retorno.", "Comandantes da Fenda tentam impedir que os aliados cheguem ao portal.", "Abra caminho até o núcleo e proteja os três selos.", [
    enemy("c18_comandante", "Comandante da Fenda", "normal", 440, 60, 205, 150, [{item:"cristal_arcano",chance:0.8}]),
    enemy("c18_colosso", "Colosso do Portal", "elite", 560, 68, 285, 205, [{item:"armadura_guardiao",chance:0.18}]),
    enemy("c18_arauto", "Arauto da Estrela", "boss", 1020, 90, 720, 520, [{item:"selo_primordial",chance:1},{item:"espada_aurora",chance:0.22}])
  ]],
  ["O Coração da Estrela", "No centro da Fenda, uma estrela consciente pulsa dentro de uma prisão feita de luz rachada e lembranças humanas.\nEla não fala com palavras: transmite imagens de um mundo destruído e de mãos que a acorrentaram para impedir que a ruína se espalhasse.\nOs selos começam a se partir, e cada fissura mostra um futuro diferente para Valedouro e para os desaparecidos.\nFragmentos estelares protegem o núcleo, não por ódio, mas por medo de serem aprisionados outra vez.\nA decisão final não será apenas derrotar uma criatura, mas compreender o preço de cada caminho antes que o cárcere desabe.", "Fragmentos estelares protegem o coração enquanto você decide como terminar o ritual.", "Sobreviva ao último teste e escolha o destino da estrela.", [
    enemy("c19_fragmento", "Fragmento Estelar", "normal", 480, 65, 225, 165, [{item:"cristal_arcano",chance:1}]),
    enemy("c19_oraculo", "Oráculo Despedaçado", "elite", 610, 73, 310, 225, [{item:"anel_sabio",chance:0.25}]),
    enemy("c19_coracao", "Coração da Estrela", "boss", 1120, 98, 800, 600, [{item:"selo_primordial",chance:1},{item:"elixir_total",chance:0.5}])
  ]],
  ["A Última Aurora", "O reino prende a respiração enquanto os três selos se encaixam e o sino de Valedouro toca através de montanhas, pântanos e cidades esquecidas.\nA corrupção reúne tudo o que roubou das pessoas desaparecidas e assume uma forma que muda a cada lembrança recuperada.\nDiante da estrela, as vozes dos sobreviventes ecoam como se estivessem ao seu lado, embora você esteja sozinho no centro da luz.\nHá mais de uma maneira de encerrar a Fenda, e nenhuma delas promete salvar tudo sem perdas.\nQuando a aurora surgir, o mundo será diferente; cabe a você escolher o que merece atravessar para o outro lado.", "A corrupção final toma forma para impedir sua decisão.", "Enfrente a manifestação final e determine o futuro de Valedouro.", [
    enemy("c20_guardiao", "Último Guardião", "normal", 520, 70, 245, 180, [{item:"escama_draconica",chance:0.6}]),
    enemy("c20_devorador", "Devorador de Auroras", "elite", 680, 80, 340, 250, [{item:"espada_aurora",chance:0.16}]),
    enemy("c20_noite", "A Noite Sem Fim", "boss", 1350, 110, 1200, 1000, [{item:"espada_aurora",chance:0.35},{item:"selo_primordial",chance:1}], "A forma final da corrupção, nascida do medo de perder o mundo.")
  ]],
];

const chapterNarratives = [
  "A névoa desceu sobre Valedouro antes do anoitecer e apagou a rua que levava à praça. As portas traziam marcas negras, mas nenhuma fechadura fora arrombada; os moradores simplesmente haviam desaparecido, deixando refeições frias sobre as mesas.\nMaelis, cartógrafa da vila, esperava junto à capela com o mapa incompleto de seu irmão Tomas. Ele tocara o sino na noite dos desaparecimentos, e agora o som vinha debaixo do poço central.\nMaelis entrega a você uma fita arrancada do sino. Ela vibra quando o som subterrâneo se repete, como se reconhecesse algo escondido sob as pedras.\nOs rastros levam à antiga praça, onde o Guardião do Sino protege uma escadaria coberta de raízes. A criatura já foi um protetor da vila; a corrupção apenas transformou seu dever em prisão.\nQuando a passagem se abre, você encontra marcas que não foram feitas por mãos humanas e um símbolo que reaparecerá em lugares distantes. Maelis reconhece o desenho no mapa: é a marca de uma estrada antiga, a Estrada dos Corvos.\nAntes de partir, ela promete manter Valedouro de pé e pede que você descubra para onde Tomas foi levado. O sino fica em silêncio pela primeira vez, mas a fita continua apontando para o norte.",
  "A Estrada dos Corvos começa além das últimas casas de Valedouro. Carroças abandonadas bloqueiam a trilha, e os pássaros repetem frases ditas por viajantes desaparecidos.\nVocê encontra Tovan, um viajante ferido que se esconde sob uma carroça. Ele reconhece a fita de Maelis: os saqueadores a copiaram em pequenos estandartes para marcar quem deveria ser levado.\nSeguindo as marcas, você descobre que os corvos não obedecem aos saqueadores; repetem uma melodia que vem de um altar escondido. Cada verso contém o nome de alguém desaparecido.\nO altar é protegido pelo Capitão dos Corvos, que recolhe lembranças e as troca por ordens gravadas em placas negras. Tovan identifica uma delas como parte de um mapa arrancado de Valedouro.\nDepois do confronto, a melodia perde força e os corvos se dispersam. Entre as placas, há uma rota para o Bosque de Miravéu e a indicação de que a corrupção se alimenta de memórias humanas.\nTovan decide acompanhar os sobreviventes até um abrigo seguro. Você segue para o bosque com a placa e a certeza de que os desaparecimentos fazem parte de algo maior.",
  "O Bosque de Miravéu parece fechar-se atrás de cada passo. As árvores repetem vozes de pessoas desaparecidas, e flores pálidas se abrem quando alguém se lembra de um nome querido.\nIria, uma botânica que estuda plantas encantadas, explica que o bosque está usando lembranças como raízes. Ela viu a mesma marca negra gravada nos troncos mais antigos.\nPara alcançar o coração do bosque, você recolhe flores luminosas sem despertar os espíritos. Cada pétala preserva uma lembrança e revela um pedaço da trilha que a névoa tenta apagar.\nUma voz dentro de uma árvore oferece mostrar o caminho em troca de uma memória sua. Iria aconselha que você não aceite o acordo: a árvore está ligada à Raiz-Mãe Corrompida, que mantém as lembranças presas.\nAo romper o núcleo da corrupção, as vozes deixam de implorar e tornam-se ecos tranquilos. Uma lembrança mostra uma ponte de pedra e soldados carregando cristais para além do desfiladeiro.\nIria guarda uma pétala intacta para estudar o fenômeno. A rota agora aponta para a Ponte de Salmour, onde alguém transportou o mesmo poder que contaminou o bosque.",
  "A Ponte de Salmour atravessa um abismo que engole até o som das pedras. Suas correntes estão partidas, e tochas azuis ardem do outro lado sem que haja alguém para alimentá-las.\nBram, um engenheiro de pontes que ficou preso entre as margens, explica que mercenários sabotaram a travessia para controlar quem passa. Ele viu carregamentos de cristais seguirem para uma fortaleza além do desfiladeiro.\nVocê ajuda Bram a examinar as correntes e encontra símbolos gravados nos encaixes. A inscrição descreve um mecanismo de contrapesos, mas alguém removeu uma peça e a levou para o posto dos mercenários.\nDo outro lado, o Carrasco da Ponte comanda as sentinelas e usa um cristal para manter a estrutura instável. Bram reconhece o objeto como parte de uma rede de condução, não uma arma comum.\nCom o cristal retirado, a ponte para de estremecer e a passagem fica segura. A inscrição completa indica que os cristais eram levados a Miralume para financiar uma guilda de contratos.\nBram permanece para reparar a travessia e ajudar quem vier atrás. Você segue para Miralume, levando a prova de que a corrupção está sendo organizada por pessoas, não apenas por monstros.",
  "Miralume brilha sob lanternas flutuantes, mas a música do mercado mal encobre as ameaças dos cobradores. Contratos negros obrigam comerciantes a entregar objetos raros a uma guilda que não consta em registro algum.\nNara, uma mercadora que conhece cada viela da cidade, oferece abrigo e conta que a guilda compra cristais vindos da Ponte de Salmour. Ela acredita que alguém está usando as dívidas para esconder o destino desses materiais.\nVocê ajuda Nara a proteger sua banca e recupera uma lanterna roubada. Quando acesa perto de um contrato, a luz revela símbolos invisíveis que apontam para as minas sob as ruas.\nO Mestre dos Contratos tenta destruir os registros antes que sejam lidos. Nara reconhece o selo em uma página: ele pertence a uma ordem antiga que deveria guardar os cristais, não negociá-los.\nCom o mestre derrotado, os contratos perdem a magia que prendia os comerciantes. Os registros mostram que a guilda alimentava um núcleo adormecido nas Minas de Vidro.\nNara organiza o mercado para resistir aos cobradores e promete levar a notícia a outras cidades. Você desce às minas antes que o núcleo desperte por completo.",
  "Sob Miralume, túneis de vidro refletem movimentos que ninguém fez. Ferramentas permanecem suspensas no ar e os nomes dos mineiros desaparecidos estão gravados por dentro das paredes cristalinas.\nDália, uma mineira que escapou por uma fenda estreita, explica que os trabalhadores encontraram um núcleo pulsante e receberam ordens para continuar escavando mesmo depois dos primeiros desaparecimentos.\nVocê encontra um mineiro preso dentro de uma camada translúcida. Ao ajustar a frequência dos cristais, pode libertá-lo sem partir a estrutura que o mantém vivo.\nO Coração de Quartzo desperta no centro da galeria. Dália percebe que o núcleo não está produzindo a corrupção: está recebendo-a de um lugar distante, como um tambor que repete o ritmo do sino de Valedouro.\nQuando o núcleo é desativado, as paredes deixam de vibrar e o mineiro consegue respirar livremente. Uma sequência de pulsos gravada na pedra corresponde a notas do sino e a coordenadas de uma abadia.\nDália entrega a você um fragmento estável e decide guiar os mineiros para fora. A próxima pista está na Abadia de Santa Véspera, onde os antigos guardiões registraram o propósito dos cristais.",
  "A Abadia de Santa Véspera ergue-se numa encosta sob uma chuva fina. Seus sinos rachados não produzem som, e um vitral mostra uma porta negra que parece mudar de lugar quando ninguém olha diretamente para ela.\nIrmão Cael, guardião ferido do arquivo, revela que os monges juraram manter em segredo a existência de uma Fenda. O voto de silêncio foi criado para impedir que uma entidade do outro lado aprendesse a imitar suas vozes.\nVocê procura a página arrancada do arquivo e encontra um juramento escrito por três ordens diferentes. A mesma marca aparece nos registros de Valedouro, confirmando que o sino fazia parte de um sistema de contenção.\nO Abade do Silêncio protege a sala proibida e tenta apagar os últimos registros. Cael reconhece no selo de seu cajado o símbolo da ordem que desviou cristais para as minas.\nCom o arquivo recuperado, a abadia volta a produzir um som baixo, quase um suspiro. Os documentos indicam que a Fenda foi alimentada por memórias roubadas e que uma torre no pântano guarda a próxima peça do mecanismo.\nCael abandona o voto para ler em voz alta os nomes dos monges desaparecidos. Você parte para o Pântano de Namar com o mapa celeste e uma advertência: não responda se a água chamar pelo seu nome.",
  "O Pântano de Namar começa onde a trilha firme afunda na lama. Bolhas pronunciam nomes esquecidos e luzes verdes se apagam sempre que alguém tenta contá-las.\nSena, uma barqueira que atravessa aquelas águas desde criança, avisa que o pântano repete as últimas palavras dos desaparecidos. Ela viu uma torre afundada fazer as águas girarem como se houvesse uma corrente sob a terra.\nPara encontrar uma rota segura, você precisa atravessar sem responder às vozes. Nas lápides cobertas de limo, um nome raspado reaparece quando a fita do sino se aproxima.\nA Noiva do Lodo guarda a entrada da torre e carrega fragmentos de lembranças presas em algas. Sena identifica uma delas como a memória de um antigo vigia que conhecia a passagem temporal.\nQuando a criatura é vencida, as águas deixam de chamar os viajantes e uma trilha de pedras emerge do lodo. O nome recuperado abre uma lembrança: o mecanismo da torre mantém um minuto repetindo-se para esconder a próxima etapa do ritual.\nSena guia os sobreviventes até terra firme e fica para marcar a rota. Você sobe à Torre de Horolog, sabendo que o tempo ali não corre como deveria.",
  "A Torre de Horolog emerge do pântano, com engrenagens girando atrás de paredes cobertas de limo. Cada andar repete a mesma sala, mas um pequeno objeto muda de lugar a cada ciclo.\nO relojoeiro Oren está preso no interior há dias. Ele explica que tentou parar o relógio depois de ver a torre repetir o desaparecimento de seus antigos companheiros, sempre no mesmo minuto.\nVocê compara duas versões da mesma sala e encontra uma chave escondida no reflexo de uma janela. Oren ajuda a ajustar as engrenagens, mas alerta que o relógio está segurando algo do lado de fora do tempo.\nO Mestre dos Segundos surge no topo e usa os ciclos para desfazer cada golpe recebido. Oren percebe que a criatura depende de um ponteiro ausente, removido e levado para o Festival da Lua Rubra.\nCom o mecanismo interrompido, os ecos deixam de repetir seus últimos instantes. A torre revela uma visão da cidade festiva e mostra que o ritual da lua está prestes a abrir uma passagem maior.\nOren permanece para estabilizar as engrenagens e libertar os presos no ciclo. Você parte para a Praça da Lua Rubra, levando o ponteiro e o aviso de que o próximo ritual será público.",
  "A Praça da Lua Rubra está coberta de máscaras e lanternas vermelhas. Os moradores dançam, mas suas sombras apontam para um palco vazio, onde um conselheiro sem sombra prepara uma cerimônia disfarçada de festa.\nNara chegou à cidade antes de você e reuniu comerciantes dispostos a expor a guilda. Ela explica que o festival é a cobertura final para um ritual que recolhe lembranças de toda a multidão.\nVocê identifica agentes infiltrados entre os mascarados e recupera uma lanterna que revela símbolos escondidos sob o palco. O ponteiro de Horolog encaixa-se num mecanismo que sincroniza a cerimônia com o sino subterrâneo.\nO Conselheiro Sem Sombra tenta completar o ritual antes que a lua alcance o centro do céu. Nara organiza os comerciantes para retirar os moradores da praça enquanto você rompe o círculo de cristais.\nO ritual é interrompido, e o primeiro Selo Primordial cai do altar. Em seus fragmentos, surge um mapa das Dunas de Cinza e uma previsão: a Fenda ficará vulnerável apenas quando três selos forem reunidos.\nNara leva os registros da guilda aos sobreviventes e promete manter aberta uma rede de apoio. Você atravessa as dunas para encontrar o observatório que previu a chegada da Fenda.",
  "As Dunas de Cinza cobrem estradas e caravanas, e à noite estrelas parecem brilhar sob a areia. Bússolas giram sem rumo enquanto uma tempestade se aproxima do horizonte.\nSamir, um guia de caravanas, perdeu parte de seu grupo ao seguir luzes que imitavam estrelas. Ele possui um mapa queimado, mas precisa de água e tempo para distinguir a rota verdadeira das miragens.\nVocê ajuda os viajantes a encontrar água e lê as constelações refletidas na cinza. Os desenhos apontam para um observatório soterrado, onde estudiosos tentaram calcular o momento em que a Fenda abriria.\nO Colosso de Areia ergue-se diante da passagem e carrega no corpo fragmentos de instrumentos astronômicos. Samir reconhece as marcas: foram arrancadas do observatório por uma tempestade criada pelo próprio ritual.\nDepois que o colosso cai, a tempestade perde força e o caminho fica visível. Entre os destroços, você encontra uma carta estelar que mostra que a Fenda não veio do céu: foi construída para aprisionar uma estrela consciente.\nSamir conduz a caravana para um abrigo e entrega a você o mapa. O Observatório de Arquen espera no alto do planalto, onde a verdade sobre a prisão poderá ser confirmada.",
  "O Observatório de Arquen permanece inclinado sobre o planalto, com lentes quebradas apontadas para um céu sem constelações. Os cálculos nas paredes terminam sempre na mesma palavra: prisão.\nLiora, uma astrônoma que sobreviveu escondida sob a cúpula, explica que a Fenda foi construída por três ordens para conter uma estrela capaz de alterar a realidade. A corrupção surgiu quando os guardiões começaram a alimentar o selo com memórias humanas.\nVocê recupera uma lente rachada e ajuda Liora a alinhar os instrumentos. A imagem revela três pontos de ancoragem: uma árvore viva, uma cidade soterrada e uma forja que guarda juramentos antigos.\nO Guardião da Lente tenta impedir a observação final. Liora mantém o mecanismo alinhado enquanto você enfrenta a sentinela, mesmo quando a imagem do outro lado parece perceber que está sendo observada.\nA lente revela uma fraqueza no selo e registra uma mensagem deixada por Tomas: ele atravessou a primeira passagem para impedir que a prisão desabasse sobre Valedouro.\nLiora copia os cálculos e segue para alertar os estudiosos restantes. Você vai à Floresta Petrificada de Elarion em busca da primeira âncora viva antes que a estrela encontre uma saída.",
  "A Floresta Petrificada de Elarion está congelada no instante de uma tempestade de luz. Folhas minerais tilintam ao vento, enquanto uma árvore azul pulsa no centro e guarda vozes de pessoas desaparecidas.\nEron, guardião das raízes antigas, explica que a árvore preserva memórias para impedir que a Fenda as devore. Ele reconhece entre os ecos a voz de Tomas e acredita que ela está presa à âncora viva.\nVocê coleta seiva mineral para tentar despertar uma sentinela petrificada. Quando a seiva toca a árvore azul, lembranças de Valedouro surgem inteiras: Tomas atravessou a passagem para reforçar o selo por dentro.\nO Coração de Pedra desperta para proteger a árvore, confundindo qualquer aproximação com uma ameaça. Eron ajuda você a distinguir a corrupção das raízes saudáveis e revela que a criatura está presa ao medo de perder as memórias que guarda.\nCom a âncora restaurada, as vozes são libertadas sem desaparecer. Uma lembrança completa mostra a segunda âncora sob uma cidade soterrada e revela que a terceira está na Forja de Vhal.\nEron permanece para proteger a árvore e as lembranças recuperadas. Você segue para Asterion com a certeza de que Tomas está vivo, mas ainda preso do outro lado.",
  "Sob as ruínas de Asterion existe uma cidade inteira, preservada por portas que não se abrem à força. Os murais mostram cidadãos apagando seus próprios nomes para esconder a cidade de uma guerra antiga.\nAveline, uma testemunha que perdeu parte das lembranças, vive entre as colunas subterrâneas. Ela recorda que os líderes de Asterion ajudaram a construir a Fenda, mas depois tentaram esconder o preço do ritual.\nVocê investiga a porta imóvel e encontra um acesso inferior por onde os construtores levavam cristais. Aveline recupera uma frase de sua memória: a cidade foi soterrada para esconder a segunda âncora e os registros da primeira traição.\nO Guardião de Asterion defende a sala dos arquivos, onde as lembranças foram comprimidas em placas de pedra. Aveline identifica a própria assinatura num decreto que ordenava apagar os nomes dos que se opuseram ao ritual.\nOs arquivos revelam que os três selos não foram criados para destruir a estrela, mas para permitir uma escolha segura quando ela despertasse. A segunda âncora começa a brilhar, e uma rota subterrânea conduz à Forja de Vhal.\nAveline decide registrar os nomes recuperados nas paredes da cidade. Você parte com os documentos e com uma pergunta que já não pode ignorar: libertar a estrela pode salvar os desaparecidos, mas também pode desfazer a prisão que mantém o mundo inteiro protegido.",
  "A Forja de Vhal arde sem combustível, alimentada por metais que guardam lembranças de quem os tocou. Cada martelada ecoa como uma promessa feita há muito tempo.\nVarek, ferreiro dos juramentos, reconhece o fragmento trazido de Asterion. Ele conta que os antigos artesãos criaram os selos com promessas de proteger tanto o mundo quanto a estrela, mas os sucessores esqueceram a segunda parte.\nVocê ajuda Varek a forjar uma peça usando metal que lembra. A cada tentativa, o material mostra uma lembrança diferente de Tomas e revela que ele reforçou o selo para ganhar tempo, não para se sacrificar.\nO Mestre da Forja tenta quebrar o juramento e tomar a peça antes que ela fique pronta. Varek enfrenta a tentação de usar o metal para recuperar alguém que perdeu, mas decide terminar o trabalho sem alterar as memórias.\nA peça final estabiliza a segunda âncora e dá forma ao segundo Selo Primordial. Os registros da forja apontam para o Mar Suspenso de Nimbária, onde a corrente que liga os selos atravessa o céu.\nVarek entrega o selo e permanece para ajudar outros ferreiros a reconstruir a forja. Você sobe rumo ao mar suspenso, levando a prova de que a prisão pode ser reparada sem apagar quem está dentro dela.",
  "O Mar Suspenso de Nimbária flutua sobre um abismo de nuvens, com navios presos em correntes que desafiam a gravidade. As velas se movem mesmo quando o vento sopra para baixo.\nA Capitã Ysra mantém sua tripulação num convés inclinado e diz que uma corrente principal está prestes a romper. Sem ela, a rota para o Reino do Avesso desaparecerá e os navios cairão no vazio.\nVocê ajuda a estabilizar o navio e traça um mapa das correntes. A rota revela que os selos funcionam como pontos de ancoragem entre realidades; a corrente principal conduz ao lugar onde a estrela mostra possibilidades que nunca aconteceram.\nO Leviatã Suspenso emerge entre as nuvens e enrola o corpo ao redor da corrente. Ysra mantém a tripulação a salvo enquanto você enfrenta a criatura, que está ferida pela mesma energia que tenta proteger.\nQuando a corrente volta a ficar estável, o caminho se abre para o Reino do Avesso. No metal do navio, surge uma mensagem de Tomas: ele viu uma terceira possibilidade, mas só pode ser encontrada no reflexo de quem decide.\nYsra promete manter a passagem aberta para o retorno. Você atravessa a corrente para um mundo invertido, onde cada escolha abandonada ganhou forma própria.",
  "O Reino do Avesso tem um céu sob os pés e montanhas suspensas como ilhas. Janelas mostram vidas que poderiam ter acontecido, e cada reflexo reage com um atraso que parece deliberado.\nNérian, um guia que perdeu o próprio reflexo, avisa que o reino tenta convencer os viajantes de que existe apenas uma escolha correta. Ele viu Tomas atravessar a praça espelhada e seguir para a fortaleza da Fenda.\nVocê encontra um reflexo ferido que não ataca; ele tenta mostrar uma lembrança escondida entre decisões que você nunca tomou. Ao ajudá-lo, descobre que a estrela não quer destruir o mundo: teme ser aprisionada de novo por quem a usa como fonte de poder.\nSeu Outro Eu surge na fortaleza e repete seus movimentos, afirmando que fechar a Fenda é a única forma de salvar Valedouro. Nérian percebe a mentira: o reflexo evita mostrar o futuro em que a estrela é libertada com os selos intactos.\nDepois do confronto, a visão se divide em três caminhos possíveis. Nenhum elimina todo risco, mas a terceira possibilidade permite abrir a prisão sem soltar a corrupção; para isso, os três selos precisam alcançar o núcleo juntos.\nNérian escolhe ficar para guiar outros viajantes perdidos. Você retorna pela corrente com a verdade e avisa os aliados: o próximo passo não é conquistar a fortaleza, mas impedir que ela destrua a única chance de escolha.",
  "A fortaleza da Fenda está cercada por sobreviventes de todas as regiões visitadas. O chão se dobra sob uma gravidade instável, e pequenas fendas tentam puxar os defensores para lugares que não existem.\nO Comandante Rovan coordena as forças aliadas e reconhece os sinais trazidos de Asterion. Ele organiza as rotas de suprimento enquanto você reúne os três selos, agora capazes de responder uns aos outros.\nVocê reabre a linha de suprimentos e recupera o estandarte da aliança. Mesmo quando uma tarefa falha, os defensores conseguem manter a posição e avançar com o essencial; cada região contribui com aquilo que conseguiu salvar.\nO Arauto da Estrela comanda a defesa do portal e tenta separar os selos. Rovan mantém a passagem aberta enquanto você atravessa o campo, onde as memórias roubadas formam paredes que mostram o sofrimento dos desaparecidos.\nCom o arauto derrotado, o portal deixa de consumir as rotas de retorno. Do outro lado, a estrela aguarda dentro da prisão rachada, e a voz de Tomas atravessa o núcleo: ele ainda sustenta o selo, mas não conseguirá mantê-lo por muito mais tempo.\nRovan conduz os aliados para fora do campo instável e confia a você a decisão final. Você entra no Coração da Estrela com os três selos e a promessa de não repetir os erros dos antigos guardiões.",
  "O Coração da Estrela pulsa dentro de uma prisão feita de luz rachada e lembranças humanas. Cada fissura mostra um futuro diferente para Valedouro, e os três selos começam a perder a força.\nUma presença chamada Aster se manifesta entre os fragmentos. Ela não fala com palavras; mostra a destruição que tentou impedir e as mãos que a acorrentaram, depois revela que Tomas permaneceu dentro do mecanismo para evitar que a prisão desabasse.\nVocê reúne as memórias dispersas e encontra uma ponte de retorno entre a estrela e Valedouro. Se a ponte falhar, os desaparecidos ficarão presos no intervalo entre os mundos, mesmo que a corrupção seja derrotada.\nO Coração da Estrela reage com medo e lança fragmentos para proteger a prisão. Aster não pede que você a liberte sem condições: pede que compreenda o que os antigos guardiões fizeram e escolha sem repetir a mentira de que só existe uma saída.\nCom a ponte estabilizada, você ouve Tomas com clareza pela primeira vez. Ele explica que os selos podem conter a corrupção sem manter a estrela em cativeiro, mas a escolha precisa ser feita antes da última âncora ruir.\nAster abre a passagem para a última aurora e devolve a você as lembranças preservadas. Você segue para o confronto final sabendo que a vitória não será medida apenas pelo inimigo derrotado, mas pelo destino que escolher para todos.",
  "A aurora não nasce enquanto a Fenda permanece aberta. Em Valedouro, Maelis e os sobreviventes acompanham o sino, que volta a tocar em intervalos regulares; cada nota atravessa as regiões e chama de volta as memórias roubadas.\nMaelis aparece através da ponte de retorno, reunindo as vozes que você libertou pelo caminho. Ela confirma que Tomas ainda está no núcleo e que a corrupção final é formada pelo medo acumulado de perder o mundo, não pela estrela em si.\nVocê encontra o último mensageiro e reconstrói a memória que faltava. A mensagem de Tomas explica como usar os três selos juntos: não para destruir a estrela, nem para deixá-la livre sem proteção, mas para transformar a prisão numa passagem controlada.\nA Noite Sem Fim toma forma diante do núcleo e assume os rostos dos desaparecidos, tentando fazer você acreditar que qualquer escolha causará a perda de todos. Maelis mantém o sino tocando do outro lado enquanto as lembranças verdadeiras desfazem as imagens falsas.\nQuando a corrupção é vencida, os três selos se encaixam e a estrela deixa de lutar contra as correntes. Você pode restaurar a prisão, libertar a estrela com os selos como ponte ou manter uma passagem aberta entre os mundos; cada escolha muda o destino da Fenda e dos que ficaram presos.\nA aurora finalmente alcança Valedouro. Tomas retorna se a ponte foi mantida, e os sobreviventes começam a reconstruir as casas e a registrar os nomes que quase foram apagados. Maelis desenha um novo mapa, não de estradas seguras, mas dos lugares que aprenderam a sobreviver juntos."
];

export const CHAPTERS = chaptersRaw.map((row, index) => ({
  number: index + 1,
  title: row[0],
  story: (chapterNarratives[index] || row[1]).split("\n")[0],
  stages: (chapterNarratives[index] || row[1]).split("\n").slice(1, 5),
  ending: (chapterNarratives[index] || row[1]).split("\n")[5] || row[1].split("\n").slice(-1)[0],
  encounterText: row[2],
  objective: row[3],
  shopAvailable: [5, 10, 15, 20].includes(index + 1),
  enemies: row[4],
}));

